require __DIR__.'/db.php';require __DIR__.'/helpers.php';
if($_SERVER['REQUEST_METHOD']!=='POST')json_out(['error'=>'Method not allowed.'],405);$ref=trim((string)(input_json()['reference']??''));if(!preg_match('/^CMB-[a-f0-9]{24}$/',$ref))json_out(['error'=>'Invalid payment reference.'],422);$s=$pdo->prepare('SELECT * FROM orders WHERE reference=?');$s->execute([$ref]);$o=$s->fetch();if(!$o)json_out(['error'=>'Order not found.'],404);if($o['status']!=='Pending Payment')json_out(['paid'=>in_array($o['status'],['Paid / Pending Delivery','Shipped'],true),'order'=>order_summary($pdo,$o)]);try{$check=verify_order_gateway($ref,$o,$config);if(!$check['ok']||abs($check['amount']-(float)$o['total'])>0.01)json_out(['paid'=>false,'error'=>'Payment is not confirmed yet.'],402);$changed=fulfill_order($pdo,$o,$check['amount']);$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$o['id']]);$o=$s->fetch();if($changed)send_mail($pdo,$o,$config);json_out(['paid'=>true,'order'=>order_summary($pdo,$o)]);}catch(Throwable $e){error_log('CMB verify '.$ref.': '.$e->getMessage());json_out(['paid'=>false,'error'=>'Payment could not be confirmed yet. Please try again shortly.'],502);}
